import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'
import { StringColumn } from '@servicenow/sdk/core'

Flow(
    {
        $id: Now.ID['7e349d264a3044fead1fe3ce8c84bbc7'],
        name: 'Test Flow for If Else Flow Logic',
        description: 'Demonstrates If Else Flow Logic',
        flowVariables: {
            user: StringColumn({
                label: 'User',
                mandatory: true,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        {
            $id: Now.ID['f752077a0dfc46c2bcd5291e47b44a4c'],
            annotation: 'Test Flow for If Else Flow Logic',
        },
        {
            table: 'incident',
            run_on_extended: 'true',
            run_when_setting: 'both',
            run_flow_in: 'any',
            condition: 'short_description="User cannot access VPN"',
            run_when_user_setting: 'not_one_of',
            run_when_user_list: [],
        }
    ),
    (_params) => {
        const actionInstance_1 = wfa.action(
            action.core.createRecord,
            {
                $id: Now.ID['b710a061df2c41d6bce8717eef028ce1'],
                annotation: 'Create VPN access incident',
            },
            {
                table_name: 'incident',
                values: TemplateValue({
                    short_description: 'User cannot access VPN',
                    description: 'User reported VPN connectivity issues',
                    impact: '2',
                    urgency: '2',
                    caller_id: wfa.dataPill(_params.flowVariables.user, 'string'),
                }),
            }
        )
        wfa.action(
            action.core.updateRecord,
            {
                $id: Now.ID['524a7240d31045d08ee1f1efcef2374d'],
                annotation: 'Assign incident to Network Support',
            },
            {
                table_name: 'incident',
                record: wfa.dataPill(actionInstance_1.record, 'string'),
                values: TemplateValue({
                    assigned_to: 'agent.smith',
                    assignment_group: 'Network Support',
                    state: '2',
                }),
            }
        )
        wfa.action(
            action.core.updateRecord,
            {
                $id: Now.ID['0682bbf06bf74ee58a230f9d628e4993'],
                annotation: 'Add initial work notes',
            },
            {
                table_name: 'incident',
                record: wfa.dataPill(actionInstance_1.record, 'string'),
                values: TemplateValue({
                    work_notes: 'Assigned to agent.smith for investigation.',
                }),
            }
        )
        const actionInstance_4 = wfa.action(
            action.core.createRecord,
            {
                $id: Now.ID['cfa5cfd20f524ce28fc5be8129b3a7dc'],
                annotation: 'Create VPN access service request',
            },
            {
                table_name: 'sc_request',
                values: TemplateValue({
                    requested_for: wfa.dataPill(_params.flowVariables.user, 'string'),
                    short_description: 'VPN Access Request',
                    description: 'Requesting access to the corporate VPN',
                    state: '1',
                }),
            }
        )
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(actionInstance_4.record, 'string')}ISNOTEMPTY`,
                annotation: 'Check if request is New',
                $id: Now.ID['cff5cdf7085b4936aa12da3932d88499'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['59463600caa641d087a851d85e96fdea'],
                        annotation: 'Log new request processing',
                        uuid: '59463600-caa6-41d0-87a8-51d85e96fdea',
                    },
                    {
                        log_level: 'info',
                        log_message: 'Processing new service request for VPN access',
                    }
                )
                wfa.flowLogic.if(
                    {
                        condition: `${wfa.dataPill(_params.trigger.current.priority, 'string')}=1`,
                        annotation: 'Check if priority is Critical',
                        $id: Now.ID['2c91d60ba4a54397a9232aff592692b7'],
                    },
                    () => {
                        wfa.action(
                            action.core.updateRecord,
                            {
                                $id: Now.ID['bea7d6c4bb184382854b910a29acc1f0'],
                                annotation: 'Update incident - Critical priority',
                            },
                            {
                                table_name: 'incident',
                                record: wfa.dataPill(_params.trigger.current.sys_id, 'string'),
                                values: TemplateValue({
                                    work_notes: 'Critical priority - expediting request.',
                                    state: '2',
                                }),
                            }
                        )
                    }
                )
                wfa.flowLogic.elseIf(
                    {
                        condition: `${wfa.dataPill(_params.trigger.current.priority, 'string')}=2`,
                        annotation: 'Check if priority is High',
                        $id: Now.ID['15bc9a1a4ae742e5a94b0c5076c353e9'],
                    },
                    () => {
                        wfa.action(
                            action.core.updateRecord,
                            {
                                $id: Now.ID['ead3df0d0b0f44368f1cecfa19321da6'],
                                annotation: 'Update incident - High priority',
                            },
                            {
                                table_name: 'incident',
                                record: wfa.dataPill(_params.trigger.current.sys_id, 'string'),
                                values: TemplateValue({
                                    work_notes: 'High priority - processing soon.',
                                    state: '2',
                                }),
                            }
                        )
                    }
                )
                wfa.flowLogic.else(
                    {
                        annotation: 'Default priority handling',
                        $id: Now.ID['609fbd1ac0c04aca821584fb84e28a41'],
                    },
                    () => {
                        wfa.action(
                            action.core.updateRecord,
                            {
                                $id: Now.ID['396f7ff5e0cc425683b7c0eceeca1a3d'],
                                annotation: 'Update incident - Standard priority',
                            },
                            {
                                table_name: 'incident',
                                record: wfa.dataPill(_params.trigger.current.sys_id, 'string'),
                                values: TemplateValue({
                                    work_notes: 'Standard priority - added to queue.',
                                    state: '2',
                                }),
                            }
                        )
                    }
                )
            }
        )
        wfa.flowLogic.elseIf(
            {
                condition: `${wfa.dataPill(actionInstance_4.record, 'string')}ISNOTEMPTY^{{Created_1.current.state}}=2`,
                annotation: 'Check if request is In Progress',
                $id: Now.ID['2e64ac4b7cc44e24bd98d6567592da2e'],
            },
            () => {
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['56d05b5ffb464abeb6d09845c4147fc1'],
                        annotation: 'Update incident - In Progress',
                    },
                    {
                        table_name: 'incident',
                        record: wfa.dataPill(_params.trigger.current.sys_id, 'string'),
                        values: TemplateValue({
                            work_notes: 'Service request already in progress.',
                            state: '2',
                        }),
                    }
                )
            }
        )
        wfa.flowLogic.elseIf(
            {
                condition: `${wfa.dataPill(actionInstance_4.record, 'string')}ISNOTEMPTY^{{Created_1.current.state}}=-5`,
                annotation: 'Check if request is Pending',
                $id: Now.ID['814d51760051475a8a19bde8c2cbb3d8'],
            },
            () => {
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['2b91ad08832b43a496467ad55d5e245a'],
                        annotation: 'Update incident - Pending approval',
                    },
                    {
                        table_name: 'incident',
                        record: wfa.dataPill(_params.trigger.current.sys_id, 'string'),
                        values: TemplateValue({
                            work_notes: 'Service request is pending approval.',
                            state: '2',
                        }),
                    }
                )
            }
        )
        wfa.flowLogic.else(
            {
                annotation: 'Default case - request completed or cancelled',
                $id: Now.ID['46525db742be4da2a912219f51cd49fa'],
            },
            () => {
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['ab9470d1d0034f1d9bd1253b9bbe318e'],
                        annotation: 'Update incident - Completed/Cancelled',
                    },
                    {
                        table_name: 'incident',
                        record: wfa.dataPill(_params.trigger.current.sys_id, 'string'),
                        values: TemplateValue({
                            work_notes: 'Service request has been completed or cancelled.',
                            state: '6',
                        }),
                    }
                )
            }
        )
    }
)
